+
+            int responseCode = connection.getResponseCode();
+            if (responseCode != HttpURLConnection.HTTP_OK) {
+                throw new RuntimeException("Failed to fetch URL, HTTP status: " + responseCode);
+            }
+
+            String charset = extractCharset(connection.getContentType());
+            String html = readContent(connection, charset);
+
+            String title = extractTitle(html);
+            String description = extractMetaDescription(html);
+
+            if (description == null || description.trim().isEmpty()) {
+                description = extractTextFallback(html);
+            }
+
+            if (title == null) {
+                title = "";
+            }
+            if (description == null) {
+                description = "";
+            }
+
+            return "Title: " + title.trim() + "\nDescription: " + description.trim();
+
+        } catch (IllegalArgumentException e) {
+            throw e;
+        } catch (Exception e) {
+            throw new RuntimeException("Failed to get URL content preview: " + e.getMessage(), e);
