+            if (connection != null) {
+                connection.disconnect();
+            }
+        }
+    }
+
+    private String extractCharset(String contentType) {
+        if (contentType != null) {
+            Matcher m = Pattern.compile("charset=([^;\\s]+)", Pattern.CASE_INSENSITIVE)
+                    .matcher(contentType);
+            if (m.find()) {
+                return m.group(1);
+            }
+        }
+        return StandardCharsets.UTF_8.name();
+    }
+
+    private String readContent(HttpURLConnection connection, String charset) throws Exception {
+        StringBuilder sb = new StringBuilder();
+        try (BufferedReader reader = new BufferedReader(
+                new InputStreamReader(connection.getInputStream(), charset))) {
+            char[] buffer = new char[4096];
+            int charsRead;
+            while ((charsRead = reader.read(buffer)) != -1) {
+                sb.append(buffer, 0, charsRead);
+                if (sb.length() > MAX_CONTENT_LENGTH) {
+                    break;
+                }
+            }
+        }
+        return sb.toString();
+    }
+
+    private String extractTitle(String html) {
+        Matcher matcher = TITLE_PATTERN.matcher(html);
+        if (matcher.find()) {
+            return decodeHtmlEntities(matcher.group(1).trim());
+        }
+        return null;
+    }
+
+    private String extractMetaDescription(String html) {
+        Matcher matcher = META_DESC_PATTERN.matcher(html);
+        if (matcher.find()) {
+            return decodeHtmlEntities(matcher.group(1).trim());
+        }
+        matcher = META_DESC_PATTERN_ALT.matcher(html);
+        if (matcher.find()) {
+            return decodeHtmlEntities(matcher.group(1).trim());
+        }
+        return null;
+    }
+
+    private String extractTextFallback(String html) {
+        String text = TAG_PATTERN.matcher(html).replaceAll(" ");
+        text = text.replaceAll("\\s+", " ").trim();
+        if (text.length() > 200) {
+            text = text.substring(0, 200);
+        }
+        return decodeHtmlEntities(text);
+    }
+
+    private String decodeHtmlEntities(String text) {
+        if (text == null) {
+            return null;
+        }
+        return text
+                .replace("&amp;", "&")
+                .replace("&lt;", "<")
+                .replace("&gt;", ">")
+                .replace("&quot;", "\"")
+                .replace("&#39;", "'")
+                .replace("&apos;", "'")
+                .replace("&#x27;", "'")
+                .replace("&nbsp;", " ");
+    }
+}

